package com.civicrepairs.adapters.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/** The {@code location} geography column is generated by PostgreSQL from latitude/longitude and not mapped. */
@Entity
@Table(name = "issue")
class IssueJpaEntity {

	@Id
	UUID id;

	@Column(name = "damage_type", nullable = false)
	String damageType;

	@Column(nullable = false)
	String status;

	@Column(nullable = false)
	double latitude;

	@Column(nullable = false)
	double longitude;

	@Column(name = "report_count", nullable = false)
	int reportCount;

	@Column(name = "opened_at", nullable = false)
	Instant openedAt;

	@Column(name = "agency_code")
	String agencyCode;

	@Column(name = "cover_media_id")
	UUID coverMediaId;

	/** Boxed on purpose: null tells Spring Data the entity is new (the id is assigned by the domain). */
	@Version
	Long version;

	/** Read-only view of the history; new transitions are inserted explicitly (append-only log). */
	@OneToMany(mappedBy = "issue")
	@OrderBy("seq")
	List<StatusTransitionJpaEntity> transitions = new ArrayList<>();
}
